// Embedded font subsets for OG card rendering.
//
// resvg-wasm has no filesystem access, so it cannot load system fonts; without
// an explicit font buffer it renders text invisibly (blank cards). These are
// subset (Latin + common punctuation) Liberation fonts — SIL Open Font License,
// metric-compatible stand-ins for the serif/mono families used in the SVGs.

const SERIF_REGULAR_B64 = "";
const SERIF_BOLD_B64 = "";
const MONO_BOLD_B64 = "";

function decode(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const SERIF_FAMILY = "Liberation Serif";
export const MONO_FAMILY = "Liberation Mono";

let cached: Uint8Array[] | null = null;
export function fontBuffers(): Uint8Array[] {
  if (!cached) cached = [decode(SERIF_REGULAR_B64), decode(SERIF_BOLD_B64), decode(MONO_BOLD_B64)];
  return cached;
}
